import{_ as d,c as r,a0 as o,o as n}from"./chunks/framework.CSihnngI.js";const s="/images/ai/LLMandAi.png",a="/images/ai/message.png",e="/images/ai/2025-05-22-023549.png",b=JSON.parse('{"title":"LLM 发展史","description":"","frontmatter":{},"headers":[],"relativePath":"majorTopic/AI/LLM/LLMHistory.md","filePath":"majorTopic/AI/LLM/LLMHistory.md","lastUpdated":1780540686000}'),l={name:"majorTopic/AI/LLM/LLMHistory.md"};function i(g,t,p,h,L,m){return n(),r("div",null,t[0]||(t[0]=[o('<h1 id="llm-发展史" tabindex="-1">LLM 发展史 <a class="header-anchor" href="#llm-发展史" aria-label="Permalink to &quot;LLM 发展史&quot;">​</a></h1><p>LLM 英文全称为 Large Language Model，中文称之为“大语言模型”。</p><h2 id="llm-与-ai" tabindex="-1">LLM 与 AI <a class="header-anchor" href="#llm-与-ai" aria-label="Permalink to &quot;LLM 与 AI&quot;">​</a></h2><p>🤔 LLM 和 AI 这个词是完全等价的？或者说 AI 就是 LLM 么？</p><p><strong>LLM 仅仅是 AI 的一个分支。</strong></p><p>AI：Artificial Intelligence 任何能够让机器模仿人类行为的技术</p><ul><li>交通程序导航</li><li>游戏里面的NPC</li></ul><p>AI 下面有很多的分支：</p><ul><li>自动驾驶</li><li>机器人</li><li>处理语言模型</li><li>处理图像模型</li><li>语音识别 .....</li></ul><p>机器学习（Machine Learning）就是其中之一。 机器学习：人类不直接给出决策规则，通过一套算法，让系统能够根据示例自己去学习，自己来做出决策。</p><p><strong>什么是深度学习?</strong></p><p>机器学习下的一个分支，这是一种 <strong>受到人脑神经系统的启发而发展出来的一种机器学习方法</strong>。通过“多层神经网络”来自动从数据中学习特征和模式，尤其擅长处理图像、语音、文本等高维、复杂的数据。</p><blockquote><p>这里仅仅是受到人脑神经的启发，不等价于复制了整个人脑。</p></blockquote><p>多层：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入层 --&gt; 隐藏层1 ---&gt; 隐藏层2 .... ---&gt; 输出层</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>每一层包含多个神经元：</p><ul><li>对输入进行加权求和</li><li>通过激活函数产生输出</li><li>输出传递给下一层</li></ul><p>这个结构越深（隐藏层越多），模型能够学到的模式就越复杂。</p><p>深度学习分支中，也不是一开始就有 Transformer 架构（模型），也是一步一步发展过来的：</p><ol><li>CNN：卷积神经网络，<strong>图像任务</strong>为主</li><li>RNN / LSTM：循环神经网络，序列任务为主</li><li>GAN：生成对抗网络，生成类任务</li><li>Transformer：多模态/<strong>语言</strong>模型/NLP为主（现已统治 DL）</li></ol><table tabindex="0"><thead><tr><th>时间</th><th>模型名</th><th>类型</th><th>应用领域</th><th>备注</th></tr></thead><tbody><tr><td>1986</td><td>MLP + 反向传播</td><td>通用神经网络</td><td>初代神经网络</td><td>Hinton 提出反向传播算法</td></tr><tr><td>1990s</td><td>RNN</td><td>循环网络</td><td>时间序列、语言建模</td><td>可记忆序列，但存在梯度消失问题</td></tr><tr><td>1997</td><td>LSTM</td><td>RNN 变体</td><td>更长序列建模</td><td>解决 RNN 梯度问题</td></tr><tr><td><strong>1998</strong></td><td><strong>LeNet-5</strong></td><td><strong>CNN</strong></td><td>图像识别（手写数字）</td><td>深度学习在图像上的首次成功</td></tr><tr><td>2012</td><td><strong>AlexNet</strong></td><td><strong>CNN</strong></td><td>图像识别</td><td>ImageNet 比赛震撼业界，DL 大爆发</td></tr><tr><td>2014</td><td>GAN</td><td>生成模型</td><td>图像生成、风格迁移</td><td>生成对抗学习首次提出</td></tr><tr><td>2014</td><td>Seq2Seq + Attention</td><td>RNN + 注意力</td><td>机器翻译</td><td>注意力机制前身，奠基 Transformer</td></tr><tr><td><strong>2017</strong></td><td><strong>Transformer</strong></td><td>自注意力</td><td>NLP，现扩展至图像/音频/多模态</td><td>无需循环/卷积，端到端强大架构</td></tr><tr><td>2018+</td><td>BERT, GPT, T5, etc.</td><td>LLM</td><td>自然语言处理</td><td>Transformer 进入爆发期</td></tr><tr><td>2021+</td><td>Diffusion Models</td><td>生成模型</td><td>图像生成（如Stable Diffusion）</td><td>GAN 之外的新方向</td></tr></tbody></table><p>Transformer 模型现在已经统治了深度学习领域：</p><table tabindex="0"><thead><tr><th>模型</th><th>是否支持序列输入</th><th>是否并行计算</th><th>主要用于</th><th>是否已被 Transformer 替代</th></tr></thead><tbody><tr><td><strong>RNN</strong></td><td>✅</td><td>❌（顺序依赖）</td><td>文本、语音</td><td>✅ 大多数已被 Transformer 替代</td></tr><tr><td><strong>LSTM/GRU</strong></td><td>✅</td><td>❌</td><td>长序列建模</td><td>✅ 被 Transformer 替代</td></tr><tr><td><strong>CNN</strong></td><td>❌</td><td>✅</td><td>图像</td><td>部分视觉任务仍使用</td></tr><tr><td><strong>Transformer</strong></td><td>✅</td><td>✅</td><td>文本、图像、音频、代码、视频</td><td>✅ 当前主流通用架构</td></tr></tbody></table><p><img src="'+s+'" alt="alt text"></p><h2 id="llm-发展路程" tabindex="-1">LLM 发展路程 <a class="header-anchor" href="#llm-发展路程" aria-label="Permalink to &quot;LLM 发展路程&quot;">​</a></h2><p>AI 技术两大核心应用方向</p><ol><li>计算机视觉（Computer Vision，CV）：让计算机看懂图片和视频，模仿人类的眼睛</li><li>自然语言处理（Natural Language Processing，NLP）：让计算机能够理解人类语言，甚至可以进行交流</li></ol><p>早期 AI 的研究突破基本都是和 CV 相关的，这几年 NLP 属于后来居上。</p><p>🤔思考：何为语言？信息又如何传播？</p><p>最早的语言，是以 <strong>声音</strong> 为媒介，通过说话进行传送的，因此使用同一种语言就显得非常重要。</p><p>不过其实，早在两千多年前，古人就研究过这个问题。古代版的普通话叫“雅言”。春秋时期，孔子的三千弟子来自五湖四海，这就必然需要孔子用一种被大家共同认可的语言来讲学。孔子用什么来讲学呢？《论语・述而第七》中记载“子所雅言，《诗》、《书》、执礼，皆雅言也。”</p><p>口头传播信息有明显的的缺点，那就是 <strong>信息非常不易积累</strong>，也很难传播。原始的人类开始使用结绳、刻契、图画的方法辅助记事，后来又用图形符号来简化、取代图画。当图形符号简化到一定程度，并形成与语言的特定对应的时候，早期的文字就形成了。因此，无论是最古老的象形文字、楔形文字，还是甲骨文，以及现代文字，它们的作用只有一个：<strong>承载信息</strong>。</p><p><img src="'+a+'" alt="信道"></p><p>同理，计算机也不能直接理解人类的自然语言，因为缺少编码和解码的过程。因此，要让计算机理解我们人类的语言，就要对语言进行编码，将其转换为计算机能够读懂的形式。</p><p>NLP 的核心任务：就是让人类语言进行某种形式的编码以及解码，让计算机能够理解人类的语言。</p><p>只有理解了人类的语言，才能完成人类给它下达的任务。</p><h2 id="nlp演进史" tabindex="-1">NLP演进史 <a class="header-anchor" href="#nlp演进史" aria-label="Permalink to &quot;NLP演进史&quot;">​</a></h2><p>分为如下 4 个阶段：</p><ol><li>起源</li><li>基于规则</li><li>基于统计</li><li>深度学习和大数据驱动</li></ol><h4 id="_1-起源" tabindex="-1">1. 起源 <a class="header-anchor" href="#_1-起源" aria-label="Permalink to &quot;1. 起源&quot;">​</a></h4><p>NLP 的起源可以追溯到阿兰・图灵在 20 世纪 50 年代提出的图灵测试。</p><p>图灵测试的基本思想：如果一个计算机程序能在自然语言对话中表现得像一个人，那么我们可以说它具有智能。</p><h4 id="_2-基于规则" tabindex="-1">2. 基于规则 <a class="header-anchor" href="#_2-基于规则" aria-label="Permalink to &quot;2. 基于规则&quot;">​</a></h4><p>在随后的数十年中，人们尝试通过基于语法和语义规则的方法来解决 NLP 问题。这也是我们人类在学习一门新的语言的时候的主要思路。</p><ul><li>一门语言的规则就非常非常多，而且十分复杂，几乎没有办法基于语法规则来建模</li><li>语言是变化的艺术</li></ul><p>下图是“现代中文主要语法关系示意图”</p><p><img src="'+e+'" alt="现代中文主要语法关系示意图"></p><h4 id="_3-基于统计" tabindex="-1">3. 基于统计 <a class="header-anchor" href="#_3-基于统计" aria-label="Permalink to &quot;3. 基于统计&quot;">​</a></h4><p>1970 年以后，以弗雷德里克・贾里尼克为首的 IBM 科学家们采用了 <strong>基于统计</strong> 的方法来解决语音识别的问题，终于把<strong>一个基于规则的问题转换成了一个数学问题</strong>，最终使 NLP 任务的准确率有了质的提升。</p><p>至此，人们才纷纷意识到原来基于规则的方法可能是行不通的，采用统计的方法才是一条正确的道路。因此，人们基于统计定义了语言模型（Language Model）</p><p>一句话解释什么是语言模型：一种捕捉自然语言中词汇、短语和句子概率分布的<strong>统计模型</strong>。</p><table tabindex="0"><thead><tr><th>模型 / 方法</th><th>简介</th></tr></thead><tbody><tr><td><strong>Bag-of-Words（BoW）</strong></td><td>最早期的文本表示方法之一，将文本看作词的集合，忽略语序，仅统计词频或词是否出现。广泛用于文本分类和信息检索。</td></tr><tr><td><strong>N-Gram 模型</strong></td><td>最具代表性的统计语言模型之一，利用前 N−1 个词预测下一个词，体现了语言的局部依赖性。</td></tr><tr><td><strong>Hidden Markov Model（HMM）</strong></td><td>一种生成式模型，广泛用于语音识别、词性标注等任务，结合状态转移概率和观测概率进行序列建模。</td></tr><tr><td><strong>Maximum Entropy Model（最大熵模型）</strong></td><td>判别式模型，可灵活建模特征对输出的影响，常用于命名实体识别、文本分类等任务。</td></tr><tr><td><strong>IBM 模型（1~5）</strong></td><td>IBM 提出的统计机器翻译模型，专注于词对齐、翻译概率和句子结构建模，对早期翻译系统影响深远。</td></tr><tr><td><strong>BLEU 指标（虽然不是模型，但重要）</strong></td><td>一种用于评估机器翻译结果的指标，衡量候选翻译与参考翻译的 n-gram 重合度，是机器翻译研究的重要标准。</td></tr></tbody></table><p>这个时期，语言模型（统计模型）就已经出现了。这个时期还不能称之为大语言模型，只能叫做语言模型。</p><h4 id="_4-深度学习和大数据驱动" tabindex="-1">4. 深度学习和大数据驱动 <a class="header-anchor" href="#_4-深度学习和大数据驱动" aria-label="Permalink to &quot;4. 深度学习和大数据驱动&quot;">​</a></h4><p>在统计方法被广泛应用之后，NLP 迎来了关键的技术飞跃——以 <strong>深度学习</strong> 和 <strong>大数据</strong> 为代表的新范式逐步取代了传统的统计模型，成为主流。这一阶段可以大致分为两个浪潮：</p><ul><li>第一波（2013～2018）：深度学习技术开始应用于 NLP，词向量（word embedding）等方法显著提升了模型的表示能力；</li><li>第二波（2018～至今）：以 Transformer 为核心架构的大规模预训练模型兴起，依托海量语料数据，实现了更强的语言理解与生成能力。</li></ul><p>深度神经网络不再只是用于特定任务的模型，而演变为通用语言表示学习工具，能够从大规模语料中自动学习语言的复杂结构与语义。</p><p>这一时期出现的<strong>大型预训练语言模型（Large Language Models, LLMs）</strong>，在众多 NLP 任务中的表现已达到甚至超越人类水平。它们不仅能处理文本分类、语音识别等传统任务，还可以进行高质量的自然语言生成，如对话系统、内容创作、机器翻译等。</p><p>该时期一些重要的语言模型：</p><table tabindex="0"><thead><tr><th>模型</th><th>简介</th></tr></thead><tbody><tr><td><strong>Word2Vec（2013）</strong></td><td>Google 提出，通过上下文学习词向量，标志着词嵌入（embedding）时代的开始。</td></tr><tr><td><strong>GloVe（2014）</strong></td><td>Stanford 提出，基于共现矩阵的全局词嵌入方法。</td></tr><tr><td><strong>ELMo（2018）</strong></td><td>使用双向 LSTM，能根据上下文动态生成词表示，是上下文词向量的开端。</td></tr><tr><td><strong>BERT（2018）</strong></td><td>Google 提出，使用 Transformer 编码器，预训练-微调范式奠定现代 NLP 基础。</td></tr><tr><td><strong>GPT 系列（2018–至今）</strong></td><td>OpenAI 提出，基于 Transformer 解码器，擅长自然语言生成，GPT-3、GPT-4 代表当今 LLM 顶尖水平。</td></tr><tr><td><strong>T5（2019）</strong></td><td>Google 提出，统一 NLP 任务为“文本到文本”的框架。</td></tr><tr><td><strong>RoBERTa、XLNet、ERNIE</strong> 等</td><td>各大公司在 BERT 基础上优化推出的改进版本。</td></tr><tr><td><strong>ChatGPT（2022）</strong>、<strong>GPT-4（2023）</strong></td><td>标志着 LLM 进入应用时代，表现出对话、编程、写作等通用能力。</td></tr></tbody></table><p>最后有一个 NLP 发展历史表：</p><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>方法 / 模型</th><th>类型</th><th>主要用途</th><th>是否考虑词序 / 语义</th></tr></thead><tbody><tr><td><strong>规则阶段</strong></td><td>1950s–1970s</td><td>语法规则、人工模板</td><td>人工构建规则系统</td><td>机器翻译、问答系统</td><td>✅ 语法结构，❌语义</td></tr><tr><td><strong>统计阶段</strong></td><td>1970s–2010s</td><td><strong>Bag-of-Words (BoW)</strong></td><td>特征表示方法</td><td>文本分类、情感分析</td><td>❌</td></tr><tr><td></td><td></td><td><strong>TF-IDF</strong></td><td>加权特征表示</td><td>文本检索、关键词提取</td><td>❌</td></tr><tr><td></td><td></td><td><strong>N-Gram</strong></td><td>统计语言模型</td><td>语言建模、机器翻译</td><td>✅ 局部上下文，❌长依赖</td></tr><tr><td></td><td></td><td><strong>HMM</strong></td><td>概率生成模型</td><td>词性标注、语音识别</td><td>✅</td></tr><tr><td></td><td></td><td><strong>IBM 模型（1~5）</strong></td><td>对齐翻译模型</td><td>统计机器翻译</td><td>✅ 局部</td></tr><tr><td><strong>深度学习阶段</strong></td><td>2013–2018</td><td><strong>Word2Vec</strong></td><td>分布式词向量</td><td>构建语义空间、分类器输入</td><td>❌（静态嵌入）</td></tr><tr><td></td><td></td><td><strong>GloVe</strong></td><td>基于矩阵的词向量</td><td>同上</td><td>❌</td></tr><tr><td></td><td></td><td><strong>ELMo</strong></td><td>上下文词向量（LSTM）</td><td>命名实体识别、问答等</td><td>✅ 局部语境</td></tr><tr><td><strong>大语言模型阶段</strong></td><td>2018–至今</td><td><strong>BERT</strong></td><td>编码器（Transformer）</td><td>预训练+微调，适用于多数 NLP 任务</td><td>✅ 深层语义</td></tr><tr><td></td><td></td><td><strong>GPT 系列（GPT-2/3/4）</strong></td><td>解码器（Transformer）</td><td>文本生成、对话系统</td><td>✅ 强上下文与推理能力</td></tr><tr><td></td><td></td><td><strong>T5</strong></td><td>编码器-解码器结构</td><td>多任务文本生成</td><td>✅</td></tr><tr><td></td><td></td><td><strong>ChatGPT</strong></td><td>应用层 LLM</td><td>对话、创作、问答</td><td>✅ 多轮对话上下文</td></tr></tbody></table>',62)]))}const N=d(l,[["render",i]]);export{b as __pageData,N as default};
